CREATE TABLE processing_instance_policies(instance_uid TEXT PRIMARY KEY REFERENCES instances,policy TEXT NOT NULL);
CREATE TABLE processing_project_policies(project_uid TEXT PRIMARY KEY REFERENCES projects,policy TEXT NOT NULL);
CREATE TABLE processing_snapshots(job_id TEXT PRIMARY KEY REFERENCES jobs(job_id),config_revision TEXT NOT NULL,snapshot TEXT NOT NULL);
CREATE TABLE processing_results(result_uid TEXT PRIMARY KEY,project_uid TEXT NOT NULL REFERENCES projects,item_uid TEXT NOT NULL REFERENCES items,revision_uid TEXT NOT NULL,policy_fingerprint TEXT NOT NULL,model_fingerprint TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('PROCESS_READY','EMBED_READY')),metadata TEXT NOT NULL,UNIQUE(revision_uid,policy_fingerprint),FOREIGN KEY(revision_uid,item_uid) REFERENCES item_revisions(revision_uid,item_uid));
CREATE TABLE processing_membership(result_uid TEXT NOT NULL REFERENCES processing_results,chunk_uid TEXT NOT NULL REFERENCES chunks,PRIMARY KEY(result_uid,chunk_uid));
CREATE TABLE processing_outcomes(job_id TEXT NOT NULL REFERENCES jobs(job_id),item_uid TEXT NOT NULL REFERENCES items,revision_uid TEXT NOT NULL,result_uid TEXT REFERENCES processing_results,state TEXT NOT NULL CHECK(state IN ('SUCCEEDED','FAILED','SKIPPED')),error_code TEXT,PRIMARY KEY(job_id,item_uid),FOREIGN KEY(revision_uid,item_uid) REFERENCES item_revisions(revision_uid,item_uid));
CREATE TABLE embedding_cache(project_uid TEXT NOT NULL REFERENCES projects,content_hash TEXT NOT NULL,model_fingerprint TEXT NOT NULL,vector_json TEXT NOT NULL,vector_digest TEXT NOT NULL,dimension INTEGER NOT NULL CHECK(dimension>0),PRIMARY KEY(project_uid,content_hash,model_fingerprint));
CREATE TABLE embedding_manifests(result_uid TEXT PRIMARY KEY REFERENCES processing_results,model_fingerprint TEXT NOT NULL,chunk_count INTEGER NOT NULL CHECK(chunk_count>=0),manifest_digest TEXT NOT NULL);
CREATE TABLE embedding_chunk_vectors(result_uid TEXT NOT NULL REFERENCES processing_results,chunk_uid TEXT NOT NULL REFERENCES chunks,project_uid TEXT NOT NULL,content_hash TEXT NOT NULL,model_fingerprint TEXT NOT NULL,PRIMARY KEY(result_uid,chunk_uid),FOREIGN KEY(project_uid,content_hash,model_fingerprint) REFERENCES embedding_cache(project_uid,content_hash,model_fingerprint));
CREATE TRIGGER processing_result_owner_insert BEFORE INSERT ON processing_results WHEN NOT EXISTS(SELECT 1 FROM items i WHERE i.item_uid=NEW.item_uid AND i.project_uid=NEW.project_uid) BEGIN SELECT RAISE(ABORT,'processing project ownership mismatch'); END;
CREATE TRIGGER processing_result_owner_update BEFORE UPDATE ON processing_results WHEN NEW.project_uid!=OLD.project_uid OR NEW.item_uid!=OLD.item_uid OR NEW.revision_uid!=OLD.revision_uid OR NEW.policy_fingerprint!=OLD.policy_fingerprint OR NEW.model_fingerprint!=OLD.model_fingerprint BEGIN SELECT RAISE(ABORT,'processing ownership immutable'); END;
CREATE TRIGGER processing_membership_owner_insert BEFORE INSERT ON processing_membership WHEN NOT EXISTS(SELECT 1 FROM processing_results r JOIN chunks c ON c.revision_uid=r.revision_uid AND c.model_fingerprint=r.model_fingerprint WHERE r.result_uid=NEW.result_uid AND c.chunk_uid=NEW.chunk_uid) BEGIN SELECT RAISE(ABORT,'processing chunk ownership mismatch'); END;
CREATE TRIGGER processing_membership_owner_update BEFORE UPDATE ON processing_membership BEGIN SELECT RAISE(ABORT,'processing membership immutable'); END;
CREATE TRIGGER processing_outcome_owner_insert BEFORE INSERT ON processing_outcomes WHEN NOT EXISTS(SELECT 1 FROM jobs j JOIN items i ON i.project_uid=j.project_uid WHERE j.job_id=NEW.job_id AND i.item_uid=NEW.item_uid) OR (NEW.result_uid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM processing_results r WHERE r.result_uid=NEW.result_uid AND r.item_uid=NEW.item_uid AND r.revision_uid=NEW.revision_uid)) BEGIN SELECT RAISE(ABORT,'processing outcome ownership mismatch'); END;
CREATE TRIGGER processing_outcome_owner_update BEFORE UPDATE ON processing_outcomes BEGIN SELECT RAISE(ABORT,'processing outcome immutable'); END;
CREATE TRIGGER embedding_vector_owner_insert BEFORE INSERT ON embedding_chunk_vectors WHEN NOT EXISTS(SELECT 1 FROM processing_results r JOIN processing_membership m USING(result_uid) JOIN chunks c USING(chunk_uid) WHERE r.result_uid=NEW.result_uid AND m.chunk_uid=NEW.chunk_uid AND r.project_uid=NEW.project_uid AND r.model_fingerprint=NEW.model_fingerprint AND c.content_hash=NEW.content_hash) BEGIN SELECT RAISE(ABORT,'embedding ownership mismatch'); END;
CREATE TRIGGER embedding_vector_owner_update BEFORE UPDATE ON embedding_chunk_vectors BEGIN SELECT RAISE(ABORT,'embedding ownership immutable'); END;
